        need(lower.interactCredential(1,actor,InteractionHand.MAIN_HAND),"rear reader borrows remaining inventory credential");saved=lower.saveWithoutMetadata(level.registryAccess());saved.getCompound("DoorRearKeyReader").putLong("TokenInsertStarted",level.getGameTime()-8);lower.loadWithComponents(saved,level.registryAccess());lower.tickCredentialReaders();need(!lower.securityToggled()&&!mate.securityToggled()&&!lower.securityOpen()&&!mate.securityOpen()&&!level.getBlockState(pos).getValue(NativeProgrammableDoorBlock.OPEN),"rear reader turns paired shared toggle off");
        need(lower.takeCredentialForDrop(0).getCount()==1&&lower.takeCredentialForDrop(1).getCount()==1&&lower.takeCredentialForDrop(0).isEmpty(),"removal ejects both sole physical owners exactly once");actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+2.5);actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.setItemInHand(InteractionHand.MAIN_HAND,NativeCredentialItems.accessCard(1));DoorLifecycleChecks.credentialPanel(true);
        try{need(actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().isEmpty()&&lower.readerProjection().front().visual().occupied(),"creative panel click remains a physical credential action");need(lower.takeCredentialForDrop(0).getCount()==1,"creative borrowed credential can be ejected once");int previousMenu=actor.containerMenu.containerId;actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));need(actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.containerMenu instanceof NativeDoorMenu menu&&menu.tile==lower&&actor.containerMenu.containerId!=previousMenu&&!lower.readerProjection().front().visual().occupied(),"held Configurizer still opens dedicated Door dialog in creative");}finally{DoorLifecycleChecks.credentialPanel(false);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);}
